USE order_query;
CREATE TABLE IF NOT EXISTS order_query_projection(order_no VARCHAR(64) PRIMARY KEY,user_id BIGINT NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL,pay_status VARCHAR(32) NOT NULL DEFAULT 'UNPAID',total_amount_cent BIGINT NOT NULL DEFAULT 0,pay_amount_cent BIGINT NOT NULL DEFAULT 0,item_count INT NOT NULL DEFAULT 0,sku_count INT NOT NULL DEFAULT 0,first_item_name VARCHAR(128),event_version INT NOT NULL DEFAULT 0,pay_time DATETIME(3),cancel_time DATETIME(3),create_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),update_time DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),KEY idx_status_time(status,create_time),KEY idx_user_time(user_id,create_time)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS mq_consume_log LIKE order_trade.mq_consume_log;
